`src/components/knowledge/BrainStatTrio.tsx:30` is explicitly commented `/** PURE — ... */` and exported for testability, but has **zero tests**. It has real untested branches: the `hasRecord` gate, the conditional `VALIDATED` cell omission when `hitRate` is null, and the sign-prefix on `iceShiftTotal`.

```ts
// src/components/knowledge/__tests__/BrainStatTrio.test.ts
import { describe, it, expect } from "bun:test";
import { deriveBrainStats } from "../BrainStatTrio";
import type { ImpactLedgerResult } from "@/lib/pm-impact.functions";

function mk(over: Partial<ImpactLedgerResult["ledger"]> = {}): ImpactLedgerResult {
  return {
    ledger: {
      decisionsTotal: 0,
      measuredOutcomes: 0,
      outcomes: { hitRate: null },
      iceShiftTotal: 0,
      decisionsTrend: [],
      ...over,
    },
    markdown: null,
  } as unknown as ImpactLedgerResult;
}

describe("deriveBrainStats", () => {
  it("returns hasRecord: false when there are no decisions and no measured outcomes", () => {
    expect(deriveBrainStats(mk())).toEqual({ hasRecord: false });
  });

  it("reports a record when decisionsTotal > 0 even with no measured outcomes", () => {
    const stats = deriveBrainStats(mk({ decisionsTotal: 3 }));
    expect(stats.hasRecord).toBe(true);
  });

  it("omits the VALIDATED cell when hitRate is null (never fabricates a rate)", () => {
    const stats = deriveBrainStats(mk({ decisionsTotal: 5, outcomes: { hitRate: null } }));
    if (!stats.hasRecord) throw new Error("expected hasRecord");
    expect(stats.cells.map((c) => c.label)).not.toContain("VALIDATED");
  });

  it("includes a rounded VALIDATED percentage when hitRate is present", () => {
    const stats = deriveBrainStats(mk({ decisionsTotal: 5, outcomes: { hitRate: 0.666 } }));
    if (!stats.hasRecord) throw new Error("expected hasRecord");
    expect(stats.cells.find((c) => c.label === "VALIDATED")?.value).toBe("67%");
  });

  it("prefixes a positive ICE shift with +, and leaves negative unprefixed", () => {
    const up = deriveBrainStats(mk({ decisionsTotal: 1, iceShiftTotal: 4 }));
    const down = deriveBrainStats(mk({ decisionsTotal: 1, iceShiftTotal: -2 }));
    if (!up.hasRecord || !down.hasRecord) throw new Error("expected hasRecord");
    expect(up.cells.find((c) => c.label === "ICE MOVED")?.value).toBe("+4");
    expect(down.cells.find((c) => c.label === "ICE MOVED")?.value).toBe("-2");
  });

  it("falls back markdown to null when the ledger's markdown is an empty string", () => {
    const stats = deriveBrainStats(mk({ decisionsTotal: 1 }));
    if (!stats.hasRecord) throw new Error("expected hasRecord");
    expect(stats.markdown).toBeNull();
  });

  it("passes decisionsTrend through unchanged", () => {
    const stats = deriveBrainStats(mk({ decisionsTotal: 1, decisionsTrend: [1, 2, 3] }));
    if (!stats.hasRecord) throw new Error("expected hasRecord");
    expect(stats.decisionsTrend).toEqual([1, 2, 3]);
  });
});
```

`src/components/governance/ConfidenceDisclosureChip.tsx:35` clamps `confidence` to `[0,1]` before rounding to a percent — that clamp is exactly the kind of boundary logic that regresses silently. No test exercises it, and none of the three `TIER_TONE`/`TIER_LABEL` branches are hit.

```tsx
// src/components/governance/__tests__/ConfidenceDisclosureChip.test.tsx
import { describe, it, expect } from "bun:test";
import { render, screen } from "@testing-library/react";
import { ConfidenceDisclosureChip } from "../ConfidenceDisclosureChip";

describe("ConfidenceDisclosureChip", () => {
  it("renders a rounded percent and the tier label", () => {
    render(<ConfidenceDisclosureChip confidence={0.82} tier="high" />);
    expect(screen.getByText("82% confident")).toBeDefined();
  });

  it("clamps confidence above 1 to 100%", () => {
    render(<ConfidenceDisclosureChip confidence={1.4} tier="high" />);
    expect(screen.getByText("100% confident")).toBeDefined();
  });

  it("clamps negative confidence to 0%", () => {
    render(<ConfidenceDisclosureChip confidence={-0.3} tier="low" />);
    expect(screen.getByText("0% unsure")).toBeDefined();
  });

  it("renders the moderate label for the medium tier", () => {
    render(<ConfidenceDisclosureChip confidence={0.5} tier="medium" />);
    expect(screen.getByText("50% moderate")).toBeDefined();
  });

  it("sets the disclosure title with the exact percent", () => {
    const { container } = render(<ConfidenceDisclosureChip confidence={0.5} tier="medium" />);
    expect(container.querySelector("span")?.title).toContain("50%");
  });
});
```

`statusLabel`, `StatusPill`, `DesignationTag`, `BestBetStamp` are all exported specifically so callers and tests can share them, yet none are exercised. The row's click/keyboard/stopPropagation wiring (lines 344–355, 490–522) is also untested — that's the part most likely to regress into a double-fire bug (card opens AND action fires).

```tsx
// src/components/discover/__tests__/OpportunityRow.test.tsx
import { describe, it, expect } from "bun:test";
import { render, screen, fireEvent } from "@testing-library/react";
import { statusLabel, StatusPill, DesignationTag, OpportunityRow } from "../OpportunityRow";

describe("statusLabel", () => {
  it("maps a known status to its sentence-case label", () => {
    expect(statusLabel("shipped")).toBe("Shipped");
  });
  it("falls back to the raw value for an unknown status (defensive)", () => {
    expect(statusLabel("weird-status")).toBe("weird-status");
  });
});

describe("StatusPill", () => {
  it("renders the mapped label for a known status", () => {
    render(<StatusPill status="now" />);
    expect(screen.getByText("Now")).toBeDefined();
  });
  it("falls back to a faint pill for an unknown status", () => {
    render(<StatusPill status="mystery" />);
    expect(screen.getByText("mystery")).toBeDefined();
  });
});

describe("DesignationTag", () => {
  it("renders nothing for the best-bet designation (it uses BestBetStamp instead)", () => {
    const { container } = render(<DesignationTag designation="best bet" />);
    expect(container.textContent).toBe("");
  });
  it("renders nothing when designation is undefined", () => {
    const { container } = render(<DesignationTag />);
    expect(container.textContent).toBe("");
  });
  it("renders the tag text and hover meaning for a non-best designation", () => {
    render(<DesignationTag designation="quick win" />);
    expect(screen.getByText("quick win")).toBeDefined();
  });
});

describe("OpportunityRow interaction", () => {
  const baseProps = {
    ice: 8.2,
    title: "Title",
    sub: "a · b",
    verdict: "SHIP" as const,
    onChallenge: () => {},
    challengePending: false,
  };

  it("calls onOpen on card click but not on action-button click (stopPropagation)", () => {
    let opened = 0;
    let challenged = 0;
    render(
      <OpportunityRow
        {...baseProps}
        onOpen={() => opened++}
        onChallenge={() => challenged++}
      />,
    );
    fireEvent.click(screen.getByText("Challenge"));
    expect(challenged).toBe(1);
    expect(opened).toBe(0); // must NOT bubble to the card's onOpen
  });

  it("opens on Enter/Space when the card itself has focus", () => {
    let opened = 0;
    render(<OpportunityRow {...baseProps} onOpen={() => opened++} />);
    fireEvent.keyDown(screen.getByRole("button", { name: "Open Title" }), { key: "Enter" });
    expect(opened).toBe(1);
  });

  it("is not a button/clickable role when onOpen is absent", () => {
    render(<OpportunityRow {...baseProps} />);
    expect(screen.queryByRole("button", { name: "Open Title" })).toBeNull();
  });

  it("colors the ICE anchor by tier: moss >=7, neutral >=4, muted below", () => {
    const { container: hi } = render(<OpportunityRow {...baseProps} ice={7.5} />);
    const { container: mid } = render(<OpportunityRow {...baseProps} ice={5} />);
    const { container: lo } = render(<OpportunityRow {...baseProps} ice={2} />);
    expect(hi.textContent).toContain("7.5");
    expect(mid.textContent).toContain("5.0");
    expect(lo.textContent).toContain("2.0");
  });
});
```

`whenOf` (line 42) and `deltaOf` (line 69) are pure, have real branches (today/yesterday/older date formatting; null-safety on `prior_ice`/`new_ice`; the "jitter under 0.1 doesn't count as a move" rule), and match the exact shape the codebase already tests elsewhere (`deriveBrainStats`, `outcomeSupportFromCounts`). They're currently module-private, so they can't be unit tested at all.

**Recommendation:** export both, then:

```ts
// src/components/knowledge/__tests__/compounding-helpers.test.ts
import { describe, it, expect } from "bun:test";
import { whenOf, deltaOf } from "../CompoundingPanel"; // after exporting

describe("deltaOf", () => {
  it("returns null when either ice value is missing", () => {
    expect(deltaOf({ prior_ice: null, new_ice: 5 })).toBeNull();
    expect(deltaOf({ prior_ice: 5, new_ice: null })).toBeNull();
  });

  it("returns null when a value is non-numeric", () => {
    expect(deltaOf({ prior_ice: "abc", new_ice: 5 })).toBeNull();
  });

  it("rounds to one decimal", () => {
    expect(deltaOf({ prior_ice: 5.03, new_ice: 5.98 })).toBe(1);
  });

  it("treats a sub-0.1 change as no move (returns null, not 0)", () => {
    expect(deltaOf({ prior_ice: 5.0, new_ice: 5.04 })).toBeNull();
  });

  it("handles string-typed ice values from the DB", () => {
    expect(deltaOf({ prior_ice: "3", new_ice: "5" })).toBe(2);
  });
});

describe("whenOf", () => {
  it("formats today's timestamp as a time-of-day string", () => {
    const now = new Date().toISOString();
    expect(whenOf(now)).toMatch(/\d{1,2}:\d{2}/);
  });

  it("formats yesterday as 'Yesterday'", () => {
    const yesterday = new Date(Date.now() - 24 * 60 * 60_000).toISOString();
    expect(whenOf(yesterday)).toBe("Yesterday");
  });

  it("formats older dates as short month/day", () => {
    const older = new Date(Date.now() - 10 * 24 * 60 * 60_000).toISOString();
    expect(whenOf(older)).toMatch(/\w{3} \d{1,2}/);
  });
});
```

The known-vs-unknown connector glyph swap (`knownProvider`, line 71) and the conditional action menu (`hasActions`, line 67) have no coverage; a broken `sourceId` lookup or an all-undefined-handlers signal would silently render wrong and nothing would fail.

```tsx
// src/components/discover/__tests__/SignalCard.test.tsx
import { describe, it, expect } from "bun:test";
import { render, screen, fireEvent } from "@testing-library/react";
import { SignalCard } from "../SignalCard";

const base = { src: "GITHUB", when: "2H AGO", quote: "A signal quote", theme: null };

describe("SignalCard", () => {
  it("shows the provider brand mark for a known connector", () => {
    const { container } = render(<SignalCard {...base} sourceId="github" />);
    expect(container.querySelector("img, svg")).toBeDefined();
  });

  it("falls back to the neutral Radio glyph for an unknown or missing sourceId", () => {
    render(<SignalCard {...base} sourceId="not-a-real-connector" />);
    expect(screen.queryByLabelText(/actions/i)).toBeNull(); // sanity: still renders
  });

  it("hides the action menu entirely when no action handlers are passed", () => {
    render(<SignalCard {...base} />);
    expect(screen.queryByLabelText("Signal actions")).toBeNull();
  });

  it("shows the action menu when at least one handler is passed", () => {
    render(<SignalCard {...base} onPromote={() => {}} />);
    expect(screen.getByLabelText("Signal actions")).toBeDefined();
  });

  it("stops propagation so opening the menu never also opens the card", () => {
    let opened = 0;
    render(<SignalCard {...base} onOpen={() => opened++} onDelete={() => {}} />);
    fireEvent.click(screen.getByLabelText("Signal actions"));
    expect(opened).toBe(0);
  });

  it("omits the divider on the last card in the feed", () => {
    const { container } = render(<SignalCard {...base} isLast />);
    const root = container.firstElementChild as HTMLElement;
    expect(root.style.borderBottom).toBe("");
  });
});
