// src/components/knowledge/__tests__/PanelSkeleton.test.tsx
import { describe, it, expect } from "bun:test";
import { render } from "@testing-library/react";
import { PanelSkeleton } from "../PanelSkeleton";

describe("PanelSkeleton", () => {
  it("renders one bar per default row height", () => {
    const { container } = render(<PanelSkeleton />);
    expect(container.querySelectorAll('[aria-hidden="true"]').length).toBe(3);
  });
  it("renders a custom number of rows", () => {
    const { container } = render(<PanelSkeleton rows={[40, 40]} />);
    expect(container.querySelectorAll('[aria-hidden="true"]').length).toBe(2);
  });
  it("narrows only the last row to 70% width", () => {
    const { container } = render(<PanelSkeleton rows={[64, 120]} />);
    const bars = container.querySelectorAll('[aria-hidden="true"]');
    expect((bars[0] as HTMLElement).style.width).toBe("100%");
    expect((bars[1] as HTMLElement).style.width).toBe("70%");
  });
  it("carries an accessible loading status role", () => {
    const { getByRole } = render(<PanelSkeleton />);
    expect(getByRole("status")).toBeDefined();
  });
});
